        "type": "list",
        "list": [
          {
            "snippet": "Go to the National Cyber Crime Reporting Portal."
          },
          {
            "snippet": "Choose File a Complaint and select your category (such as Financial Fraud or Other Cybercrime)."
          },
          {
            "snippet": "Log in using your mobile number and an OTP."
          },
          {
            "snippet": "Fill out the incident details, including the date, time, and description of the fraud."
          },
          {
            "snippet": "Upload supporting evidence like transaction receipts, bank statements, or chat screenshots."
          }
        ],
        "reference_indexes": [
